window.kbPageData["views/entry/k-9ff8c318a44234f1"] = {"key":"entry/k-9ff8c318a44234f1","state":{"route":"entry/k-9ff8c318a44234f1"},"node":{"id":"k-9ff8c318a44234f1","mode":"k","title":"消费总额、用户数与人均消费额","type":"原理与机制","domain":"统计","reading":"","intro":"","priority":100,"aliases":["消费总额等于用户数乘以人均消费额"],"qs":["江苏 2024 C类 行测#112"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"在统计时期和用户范围一致时，消费总额等于用户数乘以人均消费额。","review":{"definition":"在统计时期和用户范围一致时，消费总额等于用户数乘以人均消费额。","explanation":"人均消费额等于消费总额除以纳入统计的用户数，因此可用乘法还原总额。本题按材料口径，用2021年直播电商用户数4.3亿人乘以人均年消费额4640元，得交易额1.9952万亿元，约为2万亿元。2022年交易额为3.5万亿元，两年交易额之比约为3.5∶2，即7∶4，对应D项。","references":[],"evidence":"2021年我国直播电商行业用户数为4.3亿人，人均年消费额为4640元。","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2024 C类 行测#112":{"paper":"江苏 2024 C类 行测","n":112,"mod":"资料分析","src":["3f1ec77ae8a18519b57e.pdf",23],"asrc":["02d6b49839583bdaf297.pdf",34],"card":"3c0fb6e153e9c2dca0a13372","links":[{"id":"k-9ff8c318a44234f1","role":"解题依据","why":"用同一时期、同一统计范围内的用户数和人均消费额还原交易总额。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-9ff8c318a44234f1":[["江苏 2024 C类 行测#112"]]}};
